{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The highest-transfer analogue, Me-4FDG, showed almost no brain uptake in mice (1%ID/g at 60 min), directly demonstrating poor CNS penetration for a polar, multi-hydroxyl molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Human PET imaging with Me-4FDG confirmed that this polar scaffold does not enter the brain, providing translational evidence against meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "F-ddA achieved only 5% brain tissue/plasma concentration at steady state in rats after i.v. infusion, indicating low CNS permeability despite systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "GAZT in rhesus monkeys had a mean CSF/plasma ratio of 0.04 at 1 h, 10-fold lower than AZT and AMT, showing very limited BBB crossing for a polar nucleoside analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Digitoxin showed a very low CSF/plasma ratio (0.01-0.03) in dogs, indicating that this glycoside does not easily penetrate the BBB; the query shares multiple hydroxyl and polar features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Doxycycline hydrochloride yielded only traces of antibiotic in rat brain, confirming that a polar, H-bond-rich molecule can fail to achieve meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate poor or negligible brain/CSF uptake after systemic administration, and the query's physicochemical profile (low logD, high TPSA, multiple H-bond donors/acceptors) is consistent with poor passive permeability. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for triptolide itself is included in the evidence set.",
    "No data on active influx transporters or efflux inhibition for the query are available.",
    "No dose-response or pharmacodynamic CNS efficacy data are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

